// spec: specs/whatsapp-seller.md (2.1, 2.3) · кейсы: .qa/tests/whatsapp-seller/WA-LINK-01.md, WA-LINK-03.md
// seed: tests/seed.spec.ts (гость) · прод, только чтение (не-GET обрываются на уровне контекста, в т.ч. из SW).
// SW-сценарий — только Chromium (desktop, Android): в WebKit context.route не видит запросы через SW.
import { test, expect } from '@playwright/test';
import { prepareReadOnly, waitServiceWorker, LISTINGS, LOAD } from './whatsapp.helpers';

test.use({ serviceWorkers: 'allow' });

const CODES = ['bd5c4929', '4d62fda8', '5832e079'];
const BAD_CODES = ['00000000', 'zzz'];

test.describe('WhatsApp למוכר — короткая ссылка /b/<код>', () => {
  for (const device of ['@desktop', '@android']) {
    test(`С установленным service worker /b/<код> открывает это объявление, не «הדף לא נמצא» #1d8184 ${device} @prod-safe`, async ({ page, context }) => {
      await prepareReadOnly(context);
      await page.goto('/');
      await waitServiceWorker(page);

      for (const code of CODES) {
        await page.goto('/b/' + code);
        await page.waitForURL((u) => u.pathname === '/businessdetail', LOAD);
        expect(new URL(page.url()).searchParams.get('id'), `/b/${code} → то же объявление`).toBe(LISTINGS[code]);
        await expect(page.getByRole('button', { name: 'הצג מספר טלפון' }).first(), `/b/${code}: страница объявления отрисована`).toBeVisible(LOAD);
        await expect(page, `/b/${code}: не 404`).not.toHaveTitle(/הדף לא נמצא/);
        expect(await page.evaluate(() => !!navigator.serviceWorker.controller), 'страница под управлением SW').toBe(true);
      }
    });

    test(`С установленным service worker неверный код /b/<код> → главная, не пустая страница #1d8184 ${device} @prod-safe`, async ({ page, context }) => {
      await prepareReadOnly(context);
      await page.goto('/');
      await waitServiceWorker(page);

      for (const code of BAD_CODES) {
        await page.goto('/b/' + code);
        await page.waitForURL((u) => u.pathname === '/', LOAD);
        await expect(page, `/b/${code}: не 404`).not.toHaveTitle(/הדף לא נמצא/);
        await expect(page.getByRole('heading', { name: 'זירת העסקים של ישראל' }), `/b/${code}: содержимое главной`).toBeVisible(LOAD);
      }
    });
  }
});
